import java.util.*;

class Solution {
  public boolean twoSumBSTs(TreeNode root1, TreeNode root2, int target) {
    Set<Integer> needed = new HashSet<>();
    collect(root1, target, needed);
    return find(root2, needed);
  }

  private void collect(TreeNode n, int target, Set<Integer> needed) {
    if (n == null) return;
    needed.add(target - n.val);
    collect(n.left, target, needed);
    collect(n.right, target, needed);
  }

  private boolean find(TreeNode n, Set<Integer> needed) {
    return n != null && (needed.contains(n.val) || find(n.left, needed) || find(n.right, needed));
  }
}
